import { Routes } from '@angular/router';
import { AuthGuard } from './guards/auth.guard';

export const routes: Routes = [
  {
    path: '',
    redirectTo: '/trips',
    pathMatch: 'full'
  },
  {
    path: 'login',
    loadComponent: () => import('./components/login/login.component').then(m => m.LoginComponent)
  },
  {
    path: 'register',
    loadComponent: () => import('./components/register/register.component').then(m => m.RegisterComponent)
  },
  {
    path: 'trips',
    loadComponent: () => import('./components/trip-list/trip-list.component').then(m => m.TripListComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'add-trip',
    loadComponent: () => import('./components/trip-add/trip-add.component').then(m => m.TripAddComponent),
    canActivate: [AuthGuard]
  },
  {
    path: 'edit-trip/:id',
    loadComponent: () => import('./components/trip-edit/trip-edit.component').then(m => m.TripEditComponent),
    canActivate: [AuthGuard]
  },
  {
    path: '**',
    redirectTo: '/trips'
  }
];
